body.script:
(function() {
  var frame = document.getElementById('cmxFrame');
  var fallback = document.getElementById('fallback');
  var target = new URL('index.html', window.location.href).href;

  function showFallback() {
    fallback.hidden = false;
    window.location.replace(target);
  }

  fetch(target, { cache: 'no-store' })
    .then(function(response) {
      if (!response.ok) throw new Error('index returned ' + response.status);
      return response.text();
    })
    .then(function(html) {
      try {
        var doc = frame.contentDocument;
        if (!doc) throw new Error('iframe document unavailable');
        doc.open();
        doc.write(html);
        doc.close();
      } catch (error) {
        frame.srcdoc = html;
      }
    })
    .catch(showFallback);

  window.setTimeout(function() {
    try {
      if (!frame.contentWindow) throw new Error('iframe unavailable');
    } catch (error) {
      showFallback();
    }
  }, 2500);
})();
